import {securityCampaignOrgCampaignsCountsPath} from '@github-ui/paths'
import {useQuery} from '@github-ui/react-query'
import type {SecurityCampaignCounts} from '../types/security-campaign-counts'
import {fetchJson} from '../utils/fetch-json'
import type {AlertType} from '../types/security-campaign-alert'

export function useCampaignsCountsQuery(
  organizationLogin: string,
  initialData: SecurityCampaignCounts,
  alertType?: AlertType,
) {
  let path = securityCampaignOrgCampaignsCountsPath({org: organizationLogin})
  if (alertType) {
    const url = new URL(path, window.location.origin)
    url.searchParams.set('alert_type', alertType)
    path = `${url.pathname}?${url.searchParams.toString()}`
  }

  return useQuery<SecurityCampaignCounts>({
    queryKey: ['campaigns-counts', path, alertType ?? 'undefined'],
    queryFn: () => {
      return fetchJson(path)
    },
    initialData,
    staleTime: 1000,
  })
}
