import {RowLoading} from './RowLoading'

export function RowsLoading({rowCount}: {rowCount: number}): React.ReactElement {
  return (
    <>
      {Array.from(Array(rowCount).keys()).map(index => (
        <RowLoading key={index} />
      ))}
    </>
  )
}

try{ RowsLoading.displayName ||= 'RowsLoading' } catch {}