import {CopyIcon, SyncIcon} from '@primer/octicons-react'
import {Button, Flash, FormControl, Radio, RadioGroup, Textarea, TextInput} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useCallback, useState, type ReactNode} from 'react'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {useNavigate} from '@github-ui/use-navigate'
import {pullRequestPath} from '@github-ui/paths'
import type {Repository} from '../types/repository'
import type {PullRequest} from '../types/pull-request'
import {BranchPicker} from './BranchPicker'
import {BranchNextStepLocal} from './BranchNextStepLocal'
import {BranchNextStepFlashes} from './BranchNextStepFlashes'
import {BranchNextStepDesktop} from './BranchNextStepDesktop'

import styles from './CreateBranchDialog.module.css'

export type OnCreateBranchData = {
  branchName: string
  createNewBranch: boolean
  createPullRequest: boolean
  commitMessage: string | undefined
  extendedDescription: string | undefined

  nextStep: BranchNextStep
}

export type OnCreateBranchOptions = {
  onSuccess: (response: OnCreateBranchResponse) => void
}

export type OnCreateBranchResponse = {
  branchName: string
  pullRequest: PullRequest | null
  errorMessages: string[]
}

export type CreateBranchDialogProps = {
  repository: Repository
  branchListCacheKey: string
  branchType: BranchType
  returnFocusRef?: React.RefObject<HTMLElement>

  dialogTitle: ReactNode
  submitButtonContent: ReactNode
  warningFlashContent?: ReactNode
  showCommitMessageField?: boolean
  commitMessageRequired?: boolean
  showPullRequestNextStep?: boolean

  initialNextStep: BranchNextStep
  initialBranchName: string
  initialCommitMessage: string
  initialExtendedDescription?: string

  // onCancel is called when the user cancels the dialog before creating a branch
  onCancel?: () => void
  // onClose is called when the dialog is closed after the branch has been created
  onClose: () => void
  // onCreateBranch is called when the user submits the form to create a branch. The
  // onSuccess callback in the options must be called with the response data.
  onCreateBranch: (data: OnCreateBranchData, options: OnCreateBranchOptions) => void
  isPending: boolean
  error: Error | null
  createdPullRequest: PullRequest | null | undefined
}

export type BranchNextStep = 'local' | 'codespace' | 'desktop' | 'pr'
export type BranchType = 'new' | 'existing'

export const CreateBranchDialog = ({
  repository,
  branchListCacheKey,
  branchType,
  returnFocusRef,

  dialogTitle,
  submitButtonContent,
  warningFlashContent,
  showCommitMessageField = true,
  commitMessageRequired = false,
  showPullRequestNextStep = true,

  initialNextStep,
  initialBranchName,
  initialCommitMessage,
  initialExtendedDescription = '',

  onCancel,
  onClose,
  onCreateBranch,
  isPending,
  error,
  createdPullRequest,
}: CreateBranchDialogProps) => {
  const [showCreateBranchDialog, setShowCreateBranchDialog] = useState(true)

  const [branchNextStep, setBranchNextStep] = useState<BranchNextStep>(initialNextStep)
  const onChangeNextStep = useCallback((value: string | null) => {
    switch (value) {
      case 'codespace':
        setBranchNextStep('codespace')
        break
      case 'desktop':
        setBranchNextStep('desktop')
        break
      case 'local':
        setBranchNextStep('local')
        break
      case 'pr':
        setBranchNextStep('pr')
        break
      default:
      // Do nothing if the value is unrecognized
    }
  }, [])

  const [selectedBranchName, setSelectedBranchName] = useState<string>(branchType === 'new' ? initialBranchName : '')
  const [commitMessage, setCommitMessage] = useState<string>(initialCommitMessage)
  const [extendedDescription, setExtendedDescription] = useState<string>(initialExtendedDescription)

  const navigate = useNavigate()
  const [errorMessages, setErrorMessages] = useState<string[]>([])

  const handleCreateBranch = useCallback(async () => {
    onCreateBranch(
      {
        branchName: selectedBranchName,
        createNewBranch: branchType === 'new',
        createPullRequest: branchNextStep === 'pr',
        commitMessage: commitMessage.trim() === '' ? undefined : commitMessage,
        extendedDescription: extendedDescription.trim() === '' ? undefined : extendedDescription,
        nextStep: branchNextStep,
      },
      {
        onSuccess: ({branchName: newBranchName, pullRequest, errorMessages: newErrorMessages}) => {
          if (branchNextStep === 'pr' && pullRequest) {
            navigate(
              pullRequestPath({
                repo: pullRequest.repository,
                number: pullRequest.number,
              }),
            )
          } else {
            setSelectedBranchName(newBranchName)
            setShowCreateBranchDialog(false)
            setErrorMessages(newErrorMessages ?? [])
          }
        },
      },
    )
  }, [onCreateBranch, selectedBranchName, branchType, branchNextStep, commitMessage, extendedDescription, navigate])

  const handleCancel = useCallback(() => {
    onCancel?.()
  }, [onCancel])

  // We will show the loading state when the request is still pending, or when we have received a response and are
  // currently loading the PR page (i.e. we have a pull request in the response)
  const isLoading = isPending || !!createdPullRequest

  const isValid = selectedBranchName.trim() !== '' && (!commitMessageRequired || commitMessage.trim() !== '')

  if (!showCreateBranchDialog) {
    switch (branchNextStep) {
      case 'local':
        return (
          <BranchNextStepLocal
            branch={selectedBranchName}
            onClose={onClose}
            flashes={<BranchNextStepFlashes errorMessages={errorMessages} />}
          />
        )
      case 'desktop':
        return (
          <BranchNextStepDesktop
            owner={repository.ownerLogin}
            repository={repository.name}
            branch={selectedBranchName}
            onClose={onClose}
            flashes={<BranchNextStepFlashes errorMessages={errorMessages} />}
          />
        )
    }

    return null
  }

  return (
    <Dialog
      width="large"
      height="auto"
      onClose={handleCancel}
      title={dialogTitle}
      returnFocusRef={returnFocusRef}
      renderFooter={() => (
        <Dialog.Footer>
          <Button onClick={handleCancel}>Cancel</Button>
          <Button
            variant="primary"
            onClick={handleCreateBranch}
            leadingVisual={isLoading ? SyncIcon : null}
            disabled={isLoading || !isValid}
          >
            {submitButtonContent}
          </Button>
        </Dialog.Footer>
      )}
    >
      {error && (
        <Flash variant="danger" className={styles.flash}>
          {error.message}
        </Flash>
      )}
      {warningFlashContent ? (
        <Flash variant="warning" className={styles.flash}>
          {warningFlashContent}
        </Flash>
      ) : null}
      {branchType === 'new' && (
        <FormControl required disabled={isLoading}>
          <FormControl.Label>Branch name</FormControl.Label>
          <TextInput
            trailingAction={
              <CopyToClipboardButton
                textToCopy={selectedBranchName}
                ariaLabel="Copy branch name to clipboard"
                icon={CopyIcon}
                tooltipProps={{direction: 'w'}}
              />
            }
            value={selectedBranchName}
            onChange={e => setSelectedBranchName(e.target.value)}
            className={styles.textInput}
          />
        </FormControl>
      )}
      {branchType === 'existing' && (
        <BranchPicker
          repository={repository}
          branchListCacheKey={branchListCacheKey}
          selectedBranchName={selectedBranchName}
          onSelect={branchName => setSelectedBranchName(branchName)}
        />
      )}
      {showCommitMessageField && (
        <>
          <FormControl disabled={isLoading} required={commitMessageRequired} className={styles.formControl}>
            <FormControl.Label>Commit message</FormControl.Label>
            <TextInput
              value={commitMessage}
              onChange={e => setCommitMessage(e.target.value)}
              className={styles.textInput}
            />
            <FormControl.Caption className={styles.formControl_Caption}>
              This commit will be co-authored by Copilot Autofix
            </FormControl.Caption>
          </FormControl>
          <FormControl disabled={isLoading} className={styles.formControl}>
            <FormControl.Label>Extended description</FormControl.Label>
            <Textarea
              value={extendedDescription}
              onChange={e => setExtendedDescription(e.target.value)}
              className={styles.textInput}
            />
          </FormControl>
        </>
      )}
      <div className={styles.box}>
        <RadioGroup name="create-branch-next-action-group" onChange={onChangeNextStep} disabled={isLoading}>
          <RadioGroup.Label className={styles.radioGroup_Label}>What&apos;s next?</RadioGroup.Label>
          {showPullRequestNextStep && (
            <FormControl>
              <Radio name="create-branch-next-action" value="pr" checked={branchNextStep === 'pr'} />
              <FormControl.Label>Open a pull request</FormControl.Label>
            </FormControl>
          )}
          <FormControl>
            <Radio name="create-branch-next-action" value="local" checked={branchNextStep === 'local'} />
            <FormControl.Label>Checkout locally</FormControl.Label>
          </FormControl>
          <FormControl>
            <Radio name="create-branch-next-action" value="desktop" checked={branchNextStep === 'desktop'} />
            <FormControl.Label>Open branch with GitHub Desktop</FormControl.Label>
          </FormControl>
        </RadioGroup>
      </div>
    </Dialog>
  )
}

try{ CreateBranchDialog.displayName ||= 'CreateBranchDialog' } catch {}