import {Link} from '@primer/react'
import {CommentIcon} from '@primer/octicons-react'
import pluralize from 'pluralize'

import styles from './CampaignContactLink.module.css'

export interface CampaignContactLinkProps {
  contactLink: string | null
  teamCount: number
  userCount: number
}

export function CampaignContactLink({contactLink, teamCount, userCount}: CampaignContactLinkProps) {
  if (!contactLink) {
    return null
  }

  // Pluralize needs a number to determine the plural form
  // but we want to pluralize even if the team number is 1
  const pluralizeManager = teamCount > 0 || userCount > 1 ? 2 : 1

  return (
    <span className={styles.ContactLink}>
      <CommentIcon className="mr-1" />
      <Link href={contactLink} rel="noopener noreferrer" target="_blank">
        Contact campaign {pluralize('manager', pluralizeManager)}
      </Link>
    </span>
  )
}

try{ CampaignContactLink.displayName ||= 'CampaignContactLink' } catch {}