import {CodescanIcon, GoalIcon, KeyIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'

import {CampaignCreationButton} from './CampaignCreationButton'

import styles from './NoCampaignsBlankSlate.module.css'
import {settingsOrgSecurityProductsPath} from '@github-ui/paths'
import type {AlertType} from '../types/security-campaign-alert'

export type NoCampaignsBlankSlateProps = {
  creationAllowed: boolean
  organizationLogin: string
  maxCampaignsReached: boolean
  maxOpenCampaigns: number
  maxDraftCampaigns: number
  setIsTemplatesDialogOpen: (isOpen: boolean) => void
  aboutCampaignsDocsUrl: string
  hasSpam: boolean
  alertType?: AlertType
  displaySecretScanningCampaigns?: boolean
  setTemplateDialogType?: (type: AlertType) => void
}

export const NoCampaignsBlankSlate = ({
  creationAllowed,
  organizationLogin,
  maxCampaignsReached,
  maxOpenCampaigns,
  maxDraftCampaigns,
  setIsTemplatesDialogOpen,
  aboutCampaignsDocsUrl,
  hasSpam,
  alertType = 'code_scanning',
  displaySecretScanningCampaigns = false,
  setTemplateDialogType,
}: NoCampaignsBlankSlateProps) => {
  if (!displaySecretScanningCampaigns) {
    if (!creationAllowed) {
      return (
        <div className="border rounded-2 mb-3">
          <Blankslate spacious>
            <Blankslate.Visual>
              <GoalIcon size="medium" />
            </Blankslate.Visual>
            <Blankslate.Heading>No campaigns available</Blankslate.Heading>
            <Blankslate.Description>
              Security campaigns help teams remediate code scanning alerts with the help of Copilot Autofix.
              <br />
              <Link inline href={aboutCampaignsDocsUrl}>
                Learn more about security campaigns
              </Link>
            </Blankslate.Description>
          </Blankslate>
        </div>
      )
    }

    return (
      <div className="border rounded-2 mb-3">
        <Blankslate spacious>
          <Blankslate.Visual>
            <GoalIcon size="medium" />
          </Blankslate.Visual>
          <Blankslate.Heading>Start a new campaign</Blankslate.Heading>
          <Blankslate.Description>
            Start a new security campaign to help teams remediate code scanning alerts with the help of Copilot Autofix.
            <br />
            <Link inline href={aboutCampaignsDocsUrl}>
              Learn more about security campaigns
            </Link>
          </Blankslate.Description>
          <div className={styles.Action}>
            <CampaignCreationButton
              organizationLogin={organizationLogin}
              maxCampaignsReached={maxCampaignsReached}
              maxOpenCampaigns={maxOpenCampaigns}
              maxDraftCampaigns={maxDraftCampaigns}
              setIsTemplatesDialogOpen={setIsTemplatesDialogOpen}
              hasSpam={hasSpam}
            />
          </div>
        </Blankslate>
      </div>
    )
  }

  if (!creationAllowed) {
    if (alertType === 'code_scanning') {
      return (
        <Blankslate spacious className="border rounded-2 mb-3">
          <Blankslate.Visual>
            <CodescanIcon size="medium" />
          </Blankslate.Visual>
          <Blankslate.Heading>Remediate code vulnerabilities with Copilot Autofix</Blankslate.Heading>
          <Blankslate.Description className="mb-2">
            Enable code scanning to create campaigns and remediate vulnerabilities faster with Copilot Autofix.
          </Blankslate.Description>
          <Blankslate.PrimaryAction href={settingsOrgSecurityProductsPath({org: organizationLogin})}>
            Enable code scanning
          </Blankslate.PrimaryAction>
          <Blankslate.SecondaryAction href={aboutCampaignsDocsUrl}>
            Learn more about code scanning
          </Blankslate.SecondaryAction>
        </Blankslate>
      )
    }

    if (alertType === 'secret_scanning') {
      return (
        <Blankslate spacious className="border rounded-2 mb-3">
          <Blankslate.Visual>
            <KeyIcon size="medium" />
          </Blankslate.Visual>
          <Blankslate.Heading>Enable secret scanning</Blankslate.Heading>
          <Blankslate.Description className="mb-2">
            Enable secret scanning to accelerate the remediation of exposed secrets with security campaigns.
          </Blankslate.Description>
          <Blankslate.PrimaryAction href={settingsOrgSecurityProductsPath({org: organizationLogin})}>
            Enable secret scanning
          </Blankslate.PrimaryAction>
          <Blankslate.SecondaryAction href={aboutCampaignsDocsUrl}>
            Learn more about secret scanning
          </Blankslate.SecondaryAction>
        </Blankslate>
      )
    }

    return (
      <Blankslate spacious className="border rounded-2 mb-3">
        <Blankslate.Visual>
          <GoalIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>No campaigns available</Blankslate.Heading>
        <Blankslate.Description>
          <span className="d-block">
            Security campaigns help teams remediate code scanning alerts with the help of Copilot Autofix.
          </span>
          <Link inline href={aboutCampaignsDocsUrl}>
            Learn more about security campaigns
          </Link>
        </Blankslate.Description>
      </Blankslate>
    )
  }

  return (
    <Blankslate spacious className="border rounded-2 mb-3">
      <Blankslate.Visual>
        <GoalIcon size="medium" />
      </Blankslate.Visual>
      <Blankslate.Heading>Start a new campaign</Blankslate.Heading>
      <Blankslate.Description>
        <span className="d-block">
          Start a new security campaign to help teams remediate code scanning alerts with the help of Copilot Autofix.
        </span>
        <Link inline href={aboutCampaignsDocsUrl}>
          Learn more about security campaigns
        </Link>
      </Blankslate.Description>
      <div className={styles.Action}>
        <CampaignCreationButton
          organizationLogin={organizationLogin}
          maxCampaignsReached={maxCampaignsReached}
          maxOpenCampaigns={maxOpenCampaigns}
          maxDraftCampaigns={maxDraftCampaigns}
          setIsTemplatesDialogOpen={setIsTemplatesDialogOpen}
          hasSpam={hasSpam}
          alertType={alertType}
          setTemplateDialogType={setTemplateDialogType}
          displaySecretScanningCampaigns
        />
      </div>
    </Blankslate>
  )
}

try{ NoCampaignsBlankSlate.displayName ||= 'NoCampaignsBlankSlate' } catch {}