import {ActionList, Dialog} from '@primer/react'
import {useCallback, useState} from 'react'
import type {SecurityCampaignTemplate} from '../types/security-campaign-template'
import {ArrowRightIcon} from '@primer/octicons-react'
import {securityCampaignsOrgNewCampaignPath} from '@github-ui/paths'
import {UnderlinePanels} from '@primer/react/experimental'
import type {AlertType} from '../types/security-campaign-alert'

export type TemplateSelectionDialogProps = {
  setIsOpen: (value: boolean) => void
  codeScanningTemplates: SecurityCampaignTemplate[]
  organizationLogin: string
  displaySecretScanningTemplates?: boolean
  alertType?: AlertType | null
  anyCampaigns?: boolean
  secretScanningTemplates?: SecurityCampaignTemplate[] | null
}

export const TemplateSelectionDialog = ({
  setIsOpen,
  codeScanningTemplates,
  organizationLogin,
  displaySecretScanningTemplates = false,
  alertType = 'code_scanning',
  anyCampaigns = false,
  secretScanningTemplates = null,
}: TemplateSelectionDialogProps) => {
  const onDialogClose = useCallback(() => setIsOpen(false), [setIsOpen])
  const [activeTab, setActiveTab] = useState<AlertType>(
    alertType === 'secret_scanning' ? 'secret_scanning' : 'code_scanning',
  )

  if (!displaySecretScanningTemplates) {
    return (
      <Dialog
        title="Select a template for your campaign"
        subtitle="Start a new security campaign to help teams remediate code scanning alerts with the help of Copilot Autofix."
        onClose={onDialogClose}
      >
        <ActionList>
          {codeScanningTemplates?.map(template => (
            <ActionList.LinkItem
              href={
                template.query
                  ? securityCampaignsOrgNewCampaignPath({
                      org: organizationLogin,
                      query: template.query,
                      templateId: template.id,
                    })
                  : template.href
              }
              key={template.id}
            >
              {template.name}
              <ActionList.Description variant="block">{template.description}</ActionList.Description>
              <ActionList.TrailingVisual>
                <ArrowRightIcon />
              </ActionList.TrailingVisual>
            </ActionList.LinkItem>
          ))}
        </ActionList>
      </Dialog>
    )
  }

  const templates = alertType === 'secret_scanning' ? secretScanningTemplates : codeScanningTemplates
  return (
    <Dialog
      title="Select a template for your campaign"
      subtitle="Start a new security campaign to help teams remediate code scanning alerts with the help of Copilot Autofix."
      onClose={onDialogClose}
      renderBody={({children}) => <Dialog.Body className="p-0">{children}</Dialog.Body>}
    >
      {anyCampaigns ? (
        <UnderlinePanels aria-label="Template selector">
          <UnderlinePanels.Tab
            aria-selected={activeTab === 'code_scanning'}
            onSelect={() => {
              setActiveTab('code_scanning')
            }}
          >
            Code
          </UnderlinePanels.Tab>
          <UnderlinePanels.Tab
            aria-selected={activeTab === 'secret_scanning'}
            onSelect={() => {
              setActiveTab('secret_scanning')
            }}
          >
            Secrets
          </UnderlinePanels.Tab>
          <UnderlinePanels.Panel hidden={activeTab !== 'code_scanning'}>
            <ActionList>
              {codeScanningTemplates.map(template => (
                <ActionList.LinkItem
                  href={
                    template.query
                      ? securityCampaignsOrgNewCampaignPath({
                          org: organizationLogin,
                          query: template.query,
                          templateId: template.id,
                        })
                      : template.href
                  }
                  key={template.id}
                >
                  {template.name}
                  <ActionList.Description variant="block">{template.description}</ActionList.Description>
                  <ActionList.TrailingVisual>
                    <ArrowRightIcon />
                  </ActionList.TrailingVisual>
                </ActionList.LinkItem>
              ))}
            </ActionList>
          </UnderlinePanels.Panel>
          <UnderlinePanels.Panel hidden={activeTab !== 'secret_scanning'}>
            <ActionList>
              {secretScanningTemplates?.map(template => (
                <ActionList.LinkItem
                  href={securityCampaignsOrgNewCampaignPath({
                    org: organizationLogin,
                    query: template.query,
                    templateId: template.id,
                    alertType: 'secret_scanning',
                  })}
                  key={template.id}
                >
                  {template.name}
                  <ActionList.Description variant="block">{template.description}</ActionList.Description>
                  <ActionList.TrailingVisual>
                    <ArrowRightIcon />
                  </ActionList.TrailingVisual>
                </ActionList.LinkItem>
              ))}
            </ActionList>
          </UnderlinePanels.Panel>
        </UnderlinePanels>
      ) : (
        <ActionList>
          {templates?.map(template => (
            <ActionList.LinkItem
              href={
                template.query
                  ? securityCampaignsOrgNewCampaignPath({
                      org: organizationLogin,
                      query: template.query,
                      templateId: template.id,
                      alertType: alertType === 'secret_scanning' ? 'secret_scanning' : undefined,
                    })
                  : template.href
              }
              key={template.id}
            >
              {template.name}
              <ActionList.Description variant="block">{template.description}</ActionList.Description>
              <ActionList.TrailingVisual>
                <ArrowRightIcon />
              </ActionList.TrailingVisual>
            </ActionList.LinkItem>
          ))}
        </ActionList>
      )}
    </Dialog>
  )
}

try{ TemplateSelectionDialog.displayName ||= 'TemplateSelectionDialog' } catch {}